state.plan_ts:
/**
 * Execution-plan construction (`qlint inspect`).
 *
 * The plan fixes exactly which state fields each question may send, keeps
 * policy references separate from evidence inputs, records redaction and
 * limits with their basis, and binds the whole content to a digest so
 * `qlint run` can detect edits. Pure: the caller supplies the suite.
 */
import type { ExecutionPlan, PlanFieldProjection, PlanQuestion, QuestionSuite } from "./contracts.js";
import { digestOf } from "./digest.js";

export class PlanError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PlanError";
  }
}

export interface PlanOptions {
  version: string;
  maxRequests?: number;
  maxBytes?: number;
  maxTokens?: number;
  allowRestricted?: boolean;
}

const PROJECTION_NOTE =
  "Only the fields listed for this question are projected. Every other declared field, including evaluation targets, is excluded; excludedFieldIds records that boundary.";

function limitRationale(options: PlanOptions): string {
  const parts: string[] = [];
  if (options.maxBytes === undefined && options.maxTokens === undefined) {
    parts.push("no payload-size estimate is computed at plan time because no state values exist yet; pass --max-bytes or --max-tokens to bind request size explicitly");
  } else {
    if (options.maxBytes !== undefined) parts.push(`maxBytes=${options.maxBytes} was provided by the caller, not derived from data`);
    if (options.maxTokens !== undefined) parts.push(`maxTokens=${options.maxTokens} was provided by the caller, not derived from data`);
  }
  return parts.join("; ");
}

export function buildPlan(suite: QuestionSuite, options: PlanOptions): ExecutionPlan {
  const fields = new Map(suite.state.fields.map(field => [field.id, field]));
  const bindings = new Map(suite.bindings.map(binding => [binding.questionId, binding]));
  const questions: PlanQuestion[] = [];

  for (const question of suite.questions) {
    const binding = bindings.get(question.id);
    if (!binding) throw new PlanError(`question ${question.id} has no execution binding`);

    const toProjection = (fieldId: string): PlanFieldProjection => {
      const field = fields.get(fieldId);
      if (!field) throw new PlanError(`question ${question.id} references unknown field ${fieldId}`);
      if (field.role === "target") throw new PlanError(`question ${question.id} references evaluation target ${fieldId}`);
      return {
        fieldId: field.id,
        pointer: field.pointer,
        valueType: field.valueType,
        nullable: field.nullable,
        role: field.role,
        sensitivity: field.sensitivity,
        handling: "verbatim",
      };
    };

    const inputs = question.inputs.map(toProjection);
    const policyRefs = question.policyRefs.map(toProjection);
    const used = new Set([...question.inputs, ...question.policyRefs]);
    const excludedFieldIds = suite.state.fields.filter(field => !used.has(field.id)).map(field => field.id);
    const restrictedFieldIds = [...inputs, ...policyRefs]
      .filter(projection => projection.sensitivity === "restricted")
      .map(projection => projection.fieldId);

    if (restrictedFieldIds.length > 0 && options.allowRestricted !== true) {
      throw new PlanError(
        `restricted fields require explicit approval via --allow-restricted: ${restrictedFieldIds.join(", ")}`,
      );
    }

    const redactionNote = options.allowRestricted === true && restrictedFieldIds.length > 0
      ? `${PROJECTION_NOTE} Restricted fields were explicitly approved for projection.`
      : PROJECTION_NOTE;

    const limits: PlanQuestion["limits"] = {
      ...(options.maxBytes === undefined ? {} : { maxBytes: options.maxBytes }),
      ...(options.maxTokens === undefined ? {} : { maxTokens: options.maxTokens }),
      rationale: limitRationale(options),
    };

    questions.push({
      questionId: question.id,
      atStage: binding.atStage,
      profile: binding.profile,
      mode: question.mode,
      outputKind: question.output.kind,
      gates: binding.gates.map(gate => ({ purpose: gate.purpose, questionId: gate.questionId })),
      inputs,
      policyRefs,
      redaction: { policy: "explicit-projection-v0.1", excludedFieldIds, restrictedFieldIds, note: redactionNote },
      limits,
    });
  }

  const requestCount = questions.length;
  const maxRequests = options.maxRequests ?? requestCount;
  if (maxRequests < requestCount) {
    throw new PlanError(`--max-requests ${maxRequests} is below the ${requestCount} requests this suite requires`);
  }

  const withoutDigest = {
    schemaVersion: "0.1" as const,
    kind: "qlint.execution-plan" as const,
    tool: { name: "qlint" as const, version: options.version },
    provider: { name: "replay" as const, network: false as const },
    suite: { id: suite.id, digest: digestOf(suite) },
    questions,
    requestCount,
    maxRequests,
    notes: [
      "provider replay: this plan is executed against recorded responses only; live providers are not implemented in this bundle",
      "gate runtime and adapter normalization are not part of plan execution",
      "the plan is digest-bound; qlint run refuses content whose digest does not match",
    ],
  };
  return { ...withoutDigest, digest: digestOf(withoutDigest) };
}

export function planDigest(plan: ExecutionPlan): string {
  const { digest: _digest, ...rest } = plan;
  return digestOf(rest);
}

export function verifyPlanDigest(plan: ExecutionPlan): boolean {
  return plan.digest === planDigest(plan);
}

state.projection_ts:
/**
 * Projection of one case snapshot onto one planned question.
 *
 * This is the last boundary before a payload could reach a model, so it
 * treats the plan as authoritative: only listed fields are read, policy
 * references stay separate from evidence inputs, missing and null values
 * become abstention (never an implicit false), and type violations stop the
 * request instead of being smoothed over.
 *
 * Pure: no filesystem, network, or environment access.
 */
import type { FieldSpec, Json, PlanFieldProjection, PlanQuestion, ProjectionOutcome, ProjectionProblem } from "./contracts.js";
import { digestOf } from "./digest.js";

export function decodePointerSegment(segment: string): string {
  return segment.replace(/~1/g, "/").replace(/~0/g, "~");
}

export function resolvePointer(state: Json, pointer: string): { found: true; value: Json } | { found: false } {
  const segments = pointer.split("/").slice(1).map(decodePointerSegment);
  let current: Json = state;
  for (const segment of segments) {
    if (Array.isArray(current)) {
      if (!/^(?:0|[1-9]\d*)$/.test(segment)) return { found: false };
      const index = Number(segment);
      if (index >= current.length) return { found: false };
      current = current[index]!;
      continue;
    }
    if (typeof current === "object" && current !== null) {
      const record = current as Record<string, Json>;
      if (!(segment in record)) return { found: false };
      current = record[segment]!;
      continue;
    }
    return { found: false };
  }
  return { found: true, value: current };
}

export function matchesDeclaredType(value: Json, valueType: FieldSpec["valueType"]): boolean {
  switch (valueType) {
    case "string": return typeof value === "string";
    case "number": return typeof value === "number";
    case "integer": return typeof value === "number" && Number.isInteger(value);
    case "boolean": return typeof value === "boolean";
    case "array": return Array.isArray(value);
    case "object": return typeof value === "object" && value !== null && !Array.isArray(value);
  }
}

export function projectQuestion(question: PlanQuestion, state: Json): ProjectionOutcome {
  const inputs: Record<string, Json> = {};
  const policyRefs: Record<string, Json> = {};
  const missing: string[] = [];
  const nulls: string[] = [];
  const problems: ProjectionProblem[] = [];

  const collect = (projections: PlanFieldProjection[], target: Record<string, Json>): void => {
    for (const projection of projections) {
      // The plan type and schema already exclude targets. Widening the role
      // here is deliberate defense in depth for unvalidated hand-made plans.
      const role: string = projection.role;
      if (role === "target") {
        problems.push({
          fieldId: projection.fieldId,
          kind: "target_role",
          message: `${projection.fieldId} is an evaluation target and must not be projected`,
        });
        continue;
      }
      const resolved = resolvePointer(state, projection.pointer);
      if (!resolved.found) {
        missing.push(projection.fieldId);
        continue;
      }
      if (resolved.value === null) {
        if (projection.nullable) {
          target[projection.fieldId] = null;
        } else {
          nulls.push(projection.fieldId);
        }
        continue;
      }
      if (!matchesDeclaredType(resolved.value, projection.valueType)) {
        problems.push({
          fieldId: projection.fieldId,
          kind: "type_mismatch",
          message: `${projection.fieldId} has a value that is not ${projection.valueType}`,
        });
        continue;
      }
      target[projection.fieldId] = resolved.value;
    }
  };

  collect(question.inputs, inputs);
  collect(question.policyRefs, policyRefs);

  if (problems.length > 0) return { status: "invalid", problems };
  if (missing.length > 0) return { status: "abstained", reason: "missing_input", fieldIds: missing };
  if (nulls.length > 0) return { status: "abstained", reason: "null_value", fieldIds: nulls };

  const payload = {
    questionId: question.questionId,
    atStage: question.atStage,
    inputs,
    policyRefs,
  };
  return { status: "projected", payload, requestDigest: digestOf(payload) };
}

state.replay_ts:
/**
 * Replay runner: executes a digest-bound plan against recorded responses.
 *
 * No network, no provider, no adapter: a result either replays a recording
 * matched by request digest, abstains at projection time, reports an invalid
 * projection, or is left not_run because no recording covers it. The report
 * is itself digest-bound so repeated runs can be compared byte for byte.
 */
import type { ExecutionPlan, Json, RecordedResponse, ReplayResult, RunReport } from "./contracts.js";
import { digestOf } from "./digest.js";
import { projectQuestion } from "./projection.js";

export interface ReplayCase {
  caseId: string;
  /** Snapshot root that field pointers resolve into. */
  state: Json;
}

export class ReplayError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ReplayError";
  }
}

export function replayPlan(
  plan: ExecutionPlan,
  cases: ReplayCase[],
  recordings: RecordedResponse[],
  version: string,
): RunReport {
  const byDigest = new Map<string, Json>();
  for (const recording of recordings) {
    if (byDigest.has(recording.requestDigest)) {
      throw new ReplayError(`duplicate recorded response for ${recording.requestDigest}`);
    }
    byDigest.set(recording.requestDigest, recording.response);
  }

  const results: ReplayResult[] = [];
  for (const caseInput of cases) {
    for (const question of plan.questions) {
      const outcome = projectQuestion(question, caseInput.state);
      if (outcome.status === "abstained") {
        results.push({
          caseId: caseInput.caseId,
          questionId: question.questionId,
          status: "abstained",
          reason: outcome.reason,
        });
        continue;
      }
      if (outcome.status === "invalid") {
        results.push({
          caseId: caseInput.caseId,
          questionId: question.questionId,
          status: "invalid",
          problems: outcome.problems,
        });
        continue;
      }
      const response = byDigest.get(outcome.requestDigest);
      if (response === undefined) {
        results.push({
          caseId: caseInput.caseId,
          questionId: question.questionId,
          status: "not_run",
          requestDigest: outcome.requestDigest,
          payload: outcome.payload,
          reason: "no recorded response matches this request digest",
        });
        continue;
      }
      results.push({
        caseId: caseInput.caseId,
        questionId: question.questionId,
        status: "replayed",
        requestDigest: outcome.requestDigest,
        payload: outcome.payload,
        response,
      });
    }
  }

  const count = (status: ReplayResult["status"]): number => results.filter(result => result.status === status).length;
  const withoutDigest = {
    schemaVersion: "0.1" as const,
    kind: "qlint.run-report" as const,
    mode: "replay" as const,
    tool: { name: "qlint" as const, version },
    planDigest: plan.digest,
    suite: plan.suite,
    results,
    summary: {
      cases: cases.length,
      questions: plan.questions.length,
      replayed: count("replayed"),
      abstained: count("abstained"),
      invalid: count("invalid"),
      notRun: count("not_run"),
      requestsSent: 0,
    },
    notExecuted: [
      "adapter normalization (responses stay raw)",
      "gate runtime",
      "live provider execution (network)",
    ],
  };
  return { ...withoutDigest, digest: digestOf(withoutDigest) };
}

export function runReportDigest(report: RunReport): string {
  const { digest: _digest, ...rest } = report;
  return digestOf(rest);
}

